              {
                "label": "測量名詞定義",
                "text": "仰角：視線在水平線上方時的夾角。俯角：視線在水平線下方時的夾角。方位角：如「北 $30^circ$ 東」表示由正北向東旋轉 $30^circ$。"
              },
              {
                "label": "平面測量核心",
                "text": "將文字敘述轉化為平面三角形，利用直角三角形比例或正餘弦定理建立方程。"
              },
              {
                "label": "立體測量核心",
                "text": "涉及高度與平面方位的綜合問題，需將立體圖形拆解為數個平面三角形，並透過共同邊進行轉換計算。"
              }
