              {
                "label": "不相鄰問題",
                "text": "採取「插空隙法」，先排其他物品，再將不相鄰者插入空隙。"
              },
              {
                "label": "不盡相異物排列",
                "text": "\\(n\\) 件物品中，有 \\(m_1, m_2, \\dots\\) 件相同物，全取排列數為 \\(\\frac{n\\!}{m_1\\! m_2\\! \\dots}\\)。"
              },
              {
                "label": "重複排列",
                "text": "從 \\(n\\) 種相異物取 \\(k\\) 個排成一列，可重複選取，總數為 \\(n^k\\)。"
              },
              {
                "label": "錯排問題",
                "text": "\\(n\\) 個元素排在特定位置且皆不在原位的排列數（常利用取捨原理推導）。"
              }
